import { test, expect } from '@playwright/test';

test.describe('Registration Form Email Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="registrationForm">
        <div>
          <label for="email">Email</label>
          <input type="email" id="email" name="email" required />
        </div>
        <div>
          <label for="password">Password</label>
          <input type="password" id="password" name="password" required />
        </div>
        <button type="submit">Register</button>
      </form>
      <div id="errorMessage" style="display:none; color:red;"></div>
      <script>
        document.getElementById('registrationForm').addEventListener('submit', function(e) {
          e.preventDefault();
          const email = document.getElementById('email').value;
          const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
          const errorDiv = document.getElementById('errorMessage');

          if (!emailRegex.test(email)) {
            errorDiv.textContent = 'Please enter a valid email address';
            errorDiv.style.display = 'block';
          } else {
            errorDiv.style.display = 'none';
            alert('Registration successful');
          }
        });
      </script>
    `);
  });

  test('should display error message when submitting form with invalid email format', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const submitButton = page.getByRole('button', { name: 'Register' });

    await emailInput.fill('invalidemail');
    await passwordInput.fill('password123');
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Please enter a valid email address');
  });

  test('should display error message when submitting form with email missing domain', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const submitButton = page.getByRole('button', { name: 'Register' });

    await emailInput.fill('user@');
    await passwordInput.fill('password123');
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Please enter a valid email address');
  });

  test('should not display error message when submitting form with valid email', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const submitButton = page.getByRole('button', { name: 'Register' });

    page.once('dialog', dialog => {
      expect(dialog.message()).toBe('Registration successful');
      dialog.accept();
    });

    await emailInput.fill('valid.email@example.com');
    await passwordInput.fill('password123');
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).not.toBeVisible();
  });
});
